        best_res = min(abs(nx - rx) + abs(ny - ry) for rx, ry in resources)
        dist_opp = abs(nx - ox) + abs(ny - oy)
        return (-best_res) * 3 + dist_opp

    best = None
    best_sc = -10**18
    for dx, dy in dirs:
        nx, ny = sx + dx, sy + dy
        if 0 <= nx < w and 0 <= ny < h:
            sc = score(nx, ny)
            if sc > best_sc or (sc == best_sc and (dx, dy) < best):
                best_sc = sc
                best = (dx, dy)
